#include <stdio.h>

static int sum(const int *begin, const int *end)
{
    int total = 0;
    for (const int *cursor = begin; cursor != end; ++cursor) {
        total += *cursor;
    }
    return total;
}

int main(void)
{
    const int readings[] = {2, 8, 5};
    const int *begin = readings;
    const int *end = begin + 3;

    printf("%d\n", sum(begin, end));
    printf("%d\n", sum(begin, begin));
    return 0;
}

