#include <ctype.h>
#include <errno.h>
#include <limits.h>
#include <stdio.h>
#include <stdlib.h>

enum { READ_BAD = -1, READ_END = 0, READ_OK = 1 };

/* Read one complete line. Drain an invalid line to its newline or EOF. */
static int read_line(char line[], size_t cap)
{
    size_t used = 0;
    int ch;
    int rejected = 0;
    while ((ch = getchar()) != EOF && ch != '\n') {
        if (ch == '\0' || ch > CHAR_MAX || used == cap - 1) {
            rejected = 1;
        } else {
            line[used++] = (char)ch;
        }
    }

    if (ferror(stdin) || rejected) {
        return READ_BAD;
    }
    if (ch == EOF && used == 0) {
        return READ_END;
    }
    line[used] = '\0';
    return READ_OK;
}

static int read_integer(int low, int high, int *out)
{
    if (out == NULL) {
        return READ_BAD;
    }
    char line[64];
    int state = read_line(line, sizeof line);
    if (state != READ_OK) {
        return state;
    }

    char *end;
    errno = 0;
    long value = strtol(line, &end, 10);
    if (end == line || errno == ERANGE || value < low || value > high) {
        return READ_BAD;
    }
    while (isspace((unsigned char)*end)) {
        ++end;
    }
    if (*end != '\0') {
        return READ_BAD;
    }

    *out = (int)value;
    return READ_OK;
}

static int count_at_least(const int *begin, int length)
{
    const int *end = begin + length;
    /* TODO: keep the correct stopping position. */
    if (begin != end) {
        --end;
    }
    int total = 0;
    for (const int *cursor = begin; cursor != end; ++cursor) {
        if (*cursor >= 8) {
            ++total;
        }
    }
    return total;
}

int main(void)
{
    enum { CAPACITY = 4 };
    int readings[CAPACITY];
    int length;
    if (read_integer(0, CAPACITY, &length) != READ_OK) {
        puts("invalid");
        return 0;
    }
    for (int index = 0; index < length; ++index) {
        if (read_integer(-99, 99, &readings[index]) != READ_OK) {
            puts("invalid");
            return 0;
        }
    }
    printf("%d\n", count_at_least(readings, length));
    return 0;
}

